For reference, the example can be reduced further:

**Using `getfixturevalue`**:

``` python
import pytest


@pytest.fixture(scope='session')
def resource():
    r = [1]
    yield r
    del r[0]

@pytest.fixture(scope='session')
def sess(request):
    r = request.getfixturevalue('resource')
    yield
    assert r == [1]

@pytest.fixture(scope='function')
def func(request):
    request.getfixturevalue('resource')
    yield

def test_sess(sess):
    pass

def test_func(func):
    pass
